                    <style dangerouslySetInnerHTML={{ __html: "\n@keyframes hero12-grow {\n  0%, 54% { transform: scaleY(1) }\n  66% { transform: scaleY(0.3) }\n  100% { transform: scaleY(1) }\n}\n@keyframes hero12-rise {\n  0%, 60% { opacity: 1; transform: translateY(0) }\n  72% { opacity: 0.4; transform: translateY(4px) }\n  100% { opacity: 1; transform: translateY(0) }\n}\n@keyframes hero12-fill {\n  0%, 52% { transform: scaleX(1) }\n  64% { transform: scaleX(0.1) }\n  100% { transform: scaleX(1) }\n}\n@keyframes hero12-blink {\n  0%, 100% { opacity: 1 }\n  50% { opacity: 0.4 }\n}\n@keyframes hero12-draw {\n  0%, 50% { stroke-dashoffset: 0 }\n  62% { stroke-dashoffset: 1200 }\n  100% { stroke-dashoffset: 0 }\n}\n/* The specular pass over the whole shot. Off-canvas for most of the cycle, so\n   what registers is an occasional glint rather than a shimmer. */\n@keyframes hero12-sweep {\n  0%, 62% { opacity: 0; transform: translateX(-60%) skewX(-12deg) }\n  70% { opacity: 1 }\n  100% { opacity: 0; transform: translateX(560%) skewX(-12deg) }\n}\n\n/* Set `--hero12-delay` per element to stagger siblings; keep it a custom property,\n   because an inline `animation` shorthand would outrank the reduced-motion rule. */\n.hero12-grow,\n.hero12-rise,\n.hero12-draw,\n.hero12-track [data-slot=\"progress-indicator\"] {\n  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);\n  animation-iteration-count: infinite;\n  animation-fill-mode: both;\n  animation-delay: var(--hero12-delay, 0s);\n}\n\n.hero12-grow { animation-name: hero12-grow; animation-duration: 11.3s; }\n.hero12-rise { animation-name: hero12-rise; animation-duration: 13.7s; }\n.hero12-draw { animation-name: hero12-draw; animation-duration: 16.3s; }\n\n/* The primitive owns the indicator node, so the fill is reached through its\n   data-slot instead of a class on the element itself. */\n.hero12-track [data-slot=\"progress-indicator\"] {\n  transform-origin: left center;\n  animation-name: hero12-fill;\n  animation-duration: 10.1s;\n}\n\n.hero12-blink {\n  animation: hero12-blink 3.7s ease-in-out var(--hero12-delay, 0s) infinite;\n}\n\n.hero12-sweep {\n  opacity: 0;\n  animation: hero12-sweep 9.7s ease-in-out var(--hero12-delay, 0s) infinite;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .hero12-grow,\n  .hero12-rise,\n  .hero12-draw,\n  .hero12-blink,\n  .hero12-sweep,\n  .hero12-track [data-slot=\"progress-indicator\"] {\n    animation: none;\n  }\n  .hero12-sweep { opacity: 0; }\n}\n" }} />
